import React, { useRef } from 'react';
import { motion, useScroll, useTransform, useSpring } from 'framer-motion';
import './Contact.css';

const Contact = () => {
  const containerRef = useRef(null);

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  // Parallax elements
  const y1 = useTransform(scrollYProgress, [0, 1], [0, -150]);
  const y2 = useTransform(scrollYProgress, [0, 1], [0, -300]);
  const rotate = useTransform(scrollYProgress, [0, 1], [0, 90]);

  return (
    <section id="contact" className="ultra-contact-section" ref={containerRef}>

      {/* Immersive Animated Background */}
      <div className="contact-space-bg">
        <motion.div className="space-orb orb-1" style={{ y: y1, rotate }}></motion.div>
        <motion.div className="space-orb orb-2" style={{ y: y2, rotate: useTransform(rotate, r => -r) }}></motion.div>
        <motion.div className="space-orb orb-3" style={{ y: y1 }}></motion.div>

        {/* Dynamic Grid Overlay */}
        <div className="contact-grid-overlay"></div>
      </div>

      <div className="container relative z-10">

        {/* Header Area */}
        <motion.div
          className="contact-epic-header"
          initial={{ opacity: 0, scale: 0.8, y: 50 }}
          whileInView={{ opacity: 1, scale: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8, type: "spring", bounce: 0.4 }}
        >
          <div className="pulse-badge-container">
            <span className="pulse-badge">
              <span className="pulse-dot"></span>
              Available for Hire
            </span>
          </div>

          <h2 className="contact-mega-title">
            Let's <span className="gradient-text warp-text">Connect</span>
          </h2>
          <p className="contact-mega-subtitle">
            Ready to build the future? Drop me a message and let's create something extraordinary.
          </p>
        </motion.div>

        {/* 3D Contact Cards Container */}
        <div className="contact-3d-grid">

          {/* Email Card (Purple/Pink glow) */}
          <motion.div
            className="contact-3d-card email-card"
            initial={{ opacity: 0, x: -50, rotateY: -30 }}
            whileInView={{ opacity: 1, x: 0, rotateY: 0 }}
            viewport={{ once: true, margin: "-50px" }}
            transition={{ type: "spring", stiffness: 100, damping: 15, delay: 0.1 }}
            whileHover={{ scale: 1.05, translateY: -15, rotateX: 5, rotateY: -5 }}
          >
            <div className="card-inner-glow email-glow"></div>
            <div className="contact-icon-wrapper">
              <div className="icon-ripple"></div>
              <i className="fas fa-paper-plane"></i>
            </div>
            <h3 className="card-title">Email Me</h3>
            <p className="card-detail">pritishjadhav2006@gmail.com</p>
            <a href="mailto:pritishjadhav2006@gmail.com" className="cyber-btn email-btn">
              <span>Send Message</span>
              <i className="fas fa-arrow-right icon-slide"></i>
            </a>
          </motion.div>

          {/* WhatsApp Card (Green glow) */}
          <motion.div
            className="contact-3d-card wa-card"
            initial={{ opacity: 0, y: 50, rotateX: 30 }}
            whileInView={{ opacity: 1, y: 0, rotateX: 0 }}
            viewport={{ once: true, margin: "-50px" }}
            transition={{ type: "spring", stiffness: 100, damping: 15, delay: 0.3 }}
            whileHover={{ scale: 1.05, translateY: -15, rotateZ: 2 }}
          >
            <div className="card-inner-glow wa-glow"></div>
            <div className="contact-icon-wrapper wa-icon">
              <div className="icon-ripple wa-ripple"></div>
              <i className="fab fa-whatsapp"></i>
            </div>
            <h3 className="card-title">WhatsApp</h3>
            <p className="card-detail">+91 86057 20415</p>
            <a href="https://wa.me/918605720415" target="_blank" rel="noopener noreferrer" className="cyber-btn wa-btn">
              <span>Chat Now</span>
              <i className="fas fa-arrow-right icon-slide"></i>
            </a>
          </motion.div>

          {/* Social Network Card (Blue/Cyan glow) */}
          <motion.div
            className="contact-3d-card social-card"
            initial={{ opacity: 0, x: 50, rotateY: 30 }}
            whileInView={{ opacity: 1, x: 0, rotateY: 0 }}
            viewport={{ once: true, margin: "-50px" }}
            transition={{ type: "spring", stiffness: 100, damping: 15, delay: 0.5 }}
            whileHover={{ scale: 1.05, translateY: -15, rotateX: 5, rotateY: 5 }}
          >
            <div className="card-inner-glow social-glow"></div>
            <div className="contact-icon-wrapper social-icon">
              <div className="icon-ripple social-ripple"></div>
              <i className="fas fa-globe-americas"></i>
            </div>
            <h3 className="card-title">Social Network</h3>
            <p className="card-detail">Find me everywhere</p>

            <div className="social-nodes-container">
              <a href="https://linkedin.com/in/pritish-jadhav" target="_blank" rel="noopener noreferrer" className="social-node linkedin" title="LinkedIn">
                <i className="fab fa-linkedin-in"></i>
              </a>
              <a href="https://github.com/pritishjadhav" target="_blank" rel="noopener noreferrer" className="social-node github" title="GitHub">
                <i className="fab fa-github"></i>
              </a>
              <a href="https://x.com/Pritish2006" target="_blank" rel="noopener noreferrer" className="social-node twitter" title="Twitter">
                <i className="fab fa-twitter"></i>
              </a>
              <a href="https://www.instagram.com/jadhav_pritish_45" target="_blank" rel="noopener noreferrer" className="social-node instagram" title="Instagram">
                <i className="fab fa-instagram"></i>
              </a>
            </div>
          </motion.div>

        </div>

      </div>
    </section>
  );
};

export default Contact;
